      for j in range(i,n):
        x=random.random()**4
        S[i][j]=S[j][i]=x
    for i in range(n):
      S[i][i]+=0.1*random.random()
    P=[]
    for i in range(n):
      d=sum(S[i])
      P.append([S[i][j]/d for j in range(n)])
    M=eye(n); prev=entropy(M)
    for t in range(1,15):
      M=matmul(M,P)
      H=entropy(M)
      if H + 1e-10 < prev:
        print('found', n, trial, t, prev, H)
        for row in P: print(['%.3f'%x for x in row])
        raise SystemExit
      prev=H
print('none found')
